// "spec fn is_2_pow" from the problem statement corresponds to this pure Rust helper.
fn is_2_pow(n: i64) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

/// Returns the lower-bound insertion index for `x` within `a[lo..hi]`,
/// assuming `a[lo..hi]` is sorted in nondecreasing order.
/// The result `k` satisfies: lo <= k <= hi, all indices < k have value < x,
/// and all indices >= k have value >= x (within the range).
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    assert!(lo <= hi);
    assert!(hi <= a.len());

    let mut left = lo;
    let mut right = hi; // exclusive

    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    left
}

/// Returns the lower-bound insertion index for `x` within the first 1000 elements of `a`.
/// Assumes `a.len() >= 1000` and that `a[0..1000]` is sorted in nondecreasing order.
fn search_1000(a: &[i32], x: i32) -> usize {
    assert!(a.len() >= 1000);
    search_range_helper(a, x, 0, 1000)
}